<div class="mb-6 flex items-end justify-between"><div><p class="text-sm font-medium text-blue-600">Control diario</p><h1 class="text-2xl font-bold">Asistencia de hoy</h1></div><a href="index.php?url=asistencia_escanear" class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Escanear QR</a></div><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-5 py-4">Persona</th><th class="px-5 py-4">Entrada</th><th class="px-5 py-4">Salida</th><th class="px-5 py-4">Estado</th><th class="px-5 py-4">Tardanza</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($asistencias as $item): ?><tr><td class="px-5 py-4 font-medium"><?= htmlspecialchars($item['persona']) ?></td><td class="px-5 py-4"><?= htmlspecialchars($item['hora_entrada'] ?: '—') ?></td><td class="px-5 py-4"><?= htmlspecialchars($item['hora_salida'] ?: '—') ?></td><td class="px-5 py-4"><?= htmlspecialchars($item['estado']) ?></td><td class="px-5 py-4"><?= (int)$item['minutos_tardanza'] ?> min.</td></tr><?php endforeach; ?><?php if(!$asistencias): ?><tr><td colspan="5" class="px-5 py-12 text-center text-slate-500">No hay asistencia registrada hoy.</td></tr><?php endif; ?></tbody></table></div></section>
